<?php declare(strict_types=1);require_once __DIR__.'/../auth/seguridad.php';require_once __DIR__.'/../conexion_postgres.php';$admin=exigirAdministrador(['POST']);$d=json_decode(file_get_contents('php://input'),true);$id=filter_var($d['id']??null,FILTER_VALIDATE_INT);if($id===false||$id<1||$id===$admin)responderJson(['error'=>'No puedes eliminar este usuario.'],400);try{$q=retornarConexionPostgres()->prepare('delete from public.users where id=:id');$q->execute([':id'=>$id]);if($q->rowCount()!==1)responderJson(['error'=>'Usuario no encontrado o con pedidos asociados.'],409);responderJson(['result'=>'OK','message'=>'Usuario eliminado.']);}catch(PDOException $e){responderJson(['error'=>'No se puede eliminar un usuario con pedidos asociados.'],409);}
